export const PHILOSOPHEN=[// ---- Vorsokratiker / frühe Antike ----
{id:'thales',name:'Thales von Milet',jahre:'ca. 624–546 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['(keine eigenen Schriften überliefert)'],kernideen:['Gilt als erster Philosoph im westlichen Sinne, weil er die Welt naturphilosophisch statt mythologisch erklärte.','Sah Wasser als Urstoff (Arché), aus dem alles hervorgeht.']},{id:'anaximander',name:'Anaximander',jahre:'ca. 610–546 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['Über die Natur (Fragmente)'],kernideen:['Führte das Apeiron ein, das unbestimmte, grenzenlose Urprinzip hinter allen Dingen.','Entwarf früheste Ansätze einer naturgesetzlichen Kosmologie ohne Götter.']},{id:'anaximenes',name:'Anaximenes',jahre:'ca. 585–528 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['(Fragmente)'],kernideen:['Bestimmte Luft als Urstoff, aus dem durch Verdichtung und Verdünnung alles entsteht.']},{id:'heraklit',name:'Heraklit',jahre:'ca. 520–460 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['Fragmente (überliefert)'],kernideen:['„Alles fließt" (panta rhei) – die Welt ist ständiger Wandel.','Der Logos ist das verborgene Ordnungsprinzip, das den Wandel zusammenhält.','Gegensätze (Tag/Nacht, Leben/Tod) sind in Wahrheit eine Einheit.']},{id:'parmenides',name:'Parmenides',jahre:'ca. 515–450 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie'],werke:['Über die Natur (Lehrgedicht)'],kernideen:['Das Sein ist, das Nichtsein ist nicht – radikale Ontologie.','Veränderung und Vielheit seien nur Täuschung der Sinne; wahres Sein ist eins und unveränderlich.']},{id:'zenonelea',name:'Zenon von Elea',jahre:'ca. 490–430 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie'],werke:['(Paradoxien, überliefert)'],kernideen:['Berühmt für Paradoxien wie „Achilles und die Schildkröte", die Bewegung als logisch widersprüchlich zeigen sollen.','Verteidigte Parmenides\' These der Einheit des Seins gegen den Alltagsverstand.']},{id:'pythagoras',name:'Pythagoras',jahre:'ca. 570–495 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['(keine eigenen Schriften überliefert)'],kernideen:['Die Zahl als Wesensgrund aller Dinge.','Kosmos als harmonische, mathematisch geordnete Struktur.']},{id:'leukipp',name:'Leukipp',jahre:'ca. 5. Jhd. v. Chr. (Lebensdaten unsicher)',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['(Fragmente, meist mit Demokrit gemeinsam überliefert)'],kernideen:['Gilt neben seinem Schüler Demokrit als Mitbegründer des antiken Atomismus – die genaue Aufteilung der Ideen zwischen beiden bleibt in den Quellen oft unklar.','Vertrat, dass alles Sein letztlich aus unteilbaren, sich in der Leere bewegenden Teilchen (Atomen) besteht.','Führte damit einen konsequenten Materialismus und Determinismus in die griechische Naturphilosophie ein.']},{id:'demokrit',name:'Demokrit',jahre:'ca. 460–370 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['(Fragmente)'],kernideen:['Begründete den Atomismus: Alles besteht aus unteilbaren Atomen und leerem Raum.','Vertrat einen frühen Materialismus ohne göttliche Lenkung des Geschehens.']},{id:'protagoras',name:'Protagoras',jahre:'ca. 490–420 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Sophistik','Erkenntnistheorie'],werke:['(Fragmente)'],kernideen:['„Der Mensch ist das Maß aller Dinge" – Wahrheit ist perspektivisch relativ.','Als Sophist lehrte er Rhetorik als praktisches Werkzeug für Politik und Recht.']},{id:'gorgias',name:'Gorgias',jahre:'ca. 483–375 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Sophistik','Erkenntnistheorie'],werke:['Über das Nichtseiende'],kernideen:['Radikaler Skeptizismus: Nichts existiert, und selbst wenn, wäre es nicht erkennbar oder mitteilbar.','Meisterte Rhetorik als Kunst der Überzeugung unabhängig von objektiver Wahrheit.']},{id:'sokrates',name:'Sokrates',jahre:'469–399 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik','Erkenntnistheorie'],werke:['(keine eigenen Schriften – überliefert durch Platon)'],kernideen:['Begründete die Methode des Fragens (Mäeutik), um Scheinwissen aufzudecken.','„Ich weiß, dass ich nichts weiß" als Ausgangspunkt echter Erkenntnis.','Ethik ist wichtiger als äußerer Erfolg – ein ungeprüftes Leben sei nicht lebenswert.']},{id:'platon',name:'Platon',jahre:'428–348 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie','Politische Philosophie'],werke:['Politeia','Phaidon','Symposion'],kernideen:['Ideenlehre: Die wahre Wirklichkeit liegt in unveränderlichen, ewigen Ideen.','Die Sinnenwelt ist nur Abbild – im Höhlengleichnis illustriert.','Entwarf einen idealen Staat, geführt von philosophischen „Philosophenkönigen".','Im Symposion beschreibt er die Liebe (Eros) als aufsteigende Stufenleiter von körperlicher Anziehung bis zur reinen Schau des Schönen an sich.']},{id:'aristoteles',name:'Aristoteles',jahre:'384–322 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik','Metaphysik','Politische Philosophie'],werke:['Nikomachische Ethik','Metaphysik','Politik'],kernideen:['Begründete Logik und Empirie als systematische Methode.','Glück (Eudaimonia) als Ziel eines tugendhaften Lebens in der „goldenen Mitte".','Der Mensch ist von Natur aus ein „zoon politikon", ein soziales, politisches Wesen.','Entwickelte die Lehre von den vier Ursachen (Material-, Form-, Wirk- und Zweckursache), um vollständig zu erklären, warum etwas ist, wie es ist.']},{id:'diogenes',name:'Diogenes von Sinope',jahre:'ca. 412–323 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik'],werke:['(keine eigenen Schriften überliefert)'],kernideen:['Kynismus: radikale Bedürfnislosigkeit als Weg zur Freiheit.','Lebte demonstrativ gegen gesellschaftliche Konventionen, um Selbstgenügsamkeit zu zeigen.']},{id:'epikur',name:'Epikur',jahre:'341–270 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik'],werke:['Brief an Menoikeus'],kernideen:['Lust (im Sinne von Schmerzfreiheit, Ataraxia) als höchstes Gut.','Erreichbar durch Genügsamkeit, Freundschaft und die Überwindung der Todesfurcht.']},{id:'zenonkition',name:'Zenon von Kition',jahre:'ca. 334–262 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Ethik'],werke:['(Fragmente, Begründer der Stoa)'],kernideen:['Begründete die stoische Schule: Tugend als einziges wahres Gut.','Leben im Einklang mit der Vernunft der Natur (Logos) als Ziel.']},{id:'kleanthes',name:'Kleanthes',jahre:'ca. 330–230 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Ethik'],werke:['Hymnus an Zeus'],kernideen:['Zweites Oberhaupt der Stoa nach Zenon; verteidigte und systematisierte dessen Lehre über Jahrzehnte.','Sein „Hymnus an Zeus" ist einer der wenigen vollständig erhaltenen poetischen Stoa-Texte und verbindet Gottesbild mit dem stoischen Logos-Gedanken.','Betonte besonders die Willensunterwerfung unter das Schicksal als Kern stoischer Gelassenheit.']},{id:'chrysippos',name:'Chrysippos',jahre:'ca. 279–206 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Sprachphilosophie','Ethik'],werke:['(über 700 Schriften, fast vollständig verloren; nur Fragmente erhalten)'],kernideen:['Drittes Oberhaupt der Stoa; gilt als eigentlicher Systematiker, der die Stoa erst zu einem vollständigen philosophischen System ausbaute.','Entwickelte eine hoch entwickelte Aussagenlogik, die der modernen Junktorenlogik in vielem vorausgriff.','Vertrat einen konsequenten Determinismus („Schicksal") bei gleichzeitigem Festhalten an menschlicher Verantwortung – ein bis heute diskutiertes Kompatibilismus-Problem.']},{id:'panaitios',name:'Panaitios von Rhodos',jahre:'ca. 185–110 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Ethik'],werke:['Peri tou kathekontos (verloren, nur über Ciceros „De Officiis" bekannt)'],kernideen:['Leitete die „Mittlere Stoa" und brachte die stoische Philosophie erstmals systematisch nach Rom, wo sie großen Einfluss auf die römische Elite gewann.','Milderte einige rigide Positionen der frühen Stoa ab und machte sie praxisnäher und politisch anschlussfähiger.','Sein verlorenes Werk über das „Kathekon" (angemessenes Handeln) wurde zur Hauptquelle für Ciceros einflussreiches „De Officiis".']},{id:'poseidonios',name:'Poseidonios von Apameia',jahre:'ca. 135–51 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Metaphysik'],werke:['(umfangreiches Werk zu Philosophie, Geografie, Geschichte – nur fragmentarisch erhalten)'],kernideen:['Universalgelehrter der „Mittleren Stoa", der Philosophie mit Naturwissenschaft, Geografie und Geschichtsschreibung verband.','Prägte den Begriff der „Sympatheia" (kosmische Sympathie): Alle Teile des Universums stehen in wechselseitiger Verbindung und Wirkung zueinander.','Beeinflusste maßgeblich Cicero, der bei ihm auf Rhodos studierte, sowie spätere römische Naturphilosophie.']},{id:'musonius',name:'Musonius Rufus',jahre:'ca. 30–100 n. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Ethik'],werke:['Vorlesungen und Aussprüche (überliefert durch Schüler)'],kernideen:['Lehrer Epiktets; bekannt für eine sehr praktische, fast asketische Stoa, die sich direkt auf Ernährung, Kleidung und Alltagsverhalten bezog.','Vertrat ungewöhnlich progressiv, dass Frauen genauso wie Männer Philosophie studieren sollten, da beide gleichermaßen zur Tugend fähig seien.','Wurde unter den Kaisern Nero und Vespasian mehrfach ins Exil geschickt, blieb aber seiner philosophischen Lehrtätigkeit treu.']},{id:'epiktet',name:'Epiktet',jahre:'ca. 50–135',epoche:'Antike',tradition:'Westlich',konzepte:['Stoizismus','Ethik'],werke:['Handbüchlein der Moral (Enchiridion)'],kernideen:['Dichotomie der Kontrolle: Manches liegt in unserer Macht (Urteile, Wille), anderes nicht (äußere Ereignisse).','Wahre Freiheit besteht darin, das Unveränderliche gelassen hinzunehmen und sich nur um das eigene Urteil zu kümmern.']},{id:'seneca',name:'Seneca',jahre:'4 v. Chr.–65 n. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik','Stoizismus'],werke:['De Brevitate Vitae','Epistulae Morales'],kernideen:['Stoische Gelassenheit: Nur das eigene Urteil steht in unserer Macht.','Zeit ist der wertvollste, meist verschwendete Besitz des Menschen.']},{id:'marcaurel',name:'Marc Aurel',jahre:'121–180',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik','Stoizismus'],werke:['Selbstbetrachtungen'],kernideen:['Praktische Stoa eines römischen Kaisers: Pflichterfüllung und Gleichmut.','Ständige Erinnerung an die eigene Vergänglichkeit als Quelle innerer Ruhe.']},{id:'plotin',name:'Plotin',jahre:'204–270',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik','Neuplatonismus'],werke:['Enneaden'],kernideen:['Begründete den Neuplatonismus: Alles emaniert aus dem „Einen", einer überseienden Urquelle.','Die Seele strebt danach, sich von der Materie zu lösen und zum Einen zurückzukehren.']},{id:'boethius',name:'Boethius',jahre:'ca. 477–524',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Ethik'],werke:['Der Trost der Philosophie'],kernideen:['Verband spätantikes Denken mit dem beginnenden Mittelalter.','Fortuna (das Schicksalsrad) lehrt, wahres Glück nicht von äußeren Gütern abhängig zu machen.']},// ---- Mittelalter / Scholastik (westlich) ----
{id:'augustinus',name:'Augustinus',jahre:'354–430',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Ethik','Scholastik'],werke:['Confessiones','De Civitate Dei'],kernideen:['Verband christliche Theologie mit platonischem Denken.','Untersuchte Zeit, Erinnerung und die Rolle der göttlichen Gnade im menschlichen Willen.']},{id:'anselm',name:'Anselm von Canterbury',jahre:'1033–1109',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Scholastik'],werke:['Proslogion'],kernideen:['Ontologischer Gottesbeweis: Gott als das, worüber hinaus Größeres nicht gedacht werden kann, muss existieren.']},{id:'aquin',name:'Thomas von Aquin',jahre:'1225–1274',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Ethik','Scholastik'],werke:['Summa Theologica'],kernideen:['Höhepunkt der Scholastik: Synthese von aristotelischer Logik und christlicher Theologie.','„Glauben und Vernunft" als sich ergänzende, nicht widersprechende Wege zur Wahrheit.']},{id:'dunsscotus',name:'Duns Scotus',jahre:'ca. 1266–1308',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Scholastik'],werke:['Ordinatio'],kernideen:['Prägte den Begriff der „Haecceitas" – der individuellen, unwiederholbaren „Diesheit" eines Dings.','Betonte den Vorrang des freien Willens gegenüber dem reinen Intellekt.']},{id:'ockham',name:'Wilhelm von Ockham',jahre:'ca. 1288–1347',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Erkenntnistheorie','Scholastik'],werke:['Summa Logicae'],kernideen:['Ockhams Rasiermesser: Erkläre Phänomene mit möglichst wenigen Annahmen.','Vertrat einen Nominalismus, der die reale Existenz allgemeiner Begriffe bezweifelte.']},// ---- Nahöstlich/Islamisch & Jüdisch ----
{id:'alfarabi',name:'Al-Farabi',jahre:'ca. 872–950',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Islamische Philosophie','Politische Philosophie'],werke:['Der vollkommene Staat'],kernideen:['Verband platonisch-aristotelisches Denken mit islamischer Theologie.','Entwarf das Bild eines „vollkommenen Staates", geleitet von einem philosophisch gebildeten Herrscher.']},{id:'avicenna',name:'Avicenna (Ibn Sina)',jahre:'980–1037',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Islamische Philosophie','Metaphysik'],werke:['Das Buch der Genesung'],kernideen:['Unterschied grundlegend zwischen „Wesen" (was etwas ist) und „Existenz" (dass etwas ist).','Prägte durch seine Medizin- und Logikwerke auch die spätere europäische Scholastik.']},{id:'alghazali',name:'Al-Ghazali',jahre:'1058–1111',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Islamische Philosophie','Erkenntnistheorie'],werke:['Die Inkohärenz der Philosophen'],kernideen:['Kritisierte die griechisch geprägte Philosophie zugunsten einer auf Offenbarung gestützten Erkenntnis.','Fand persönliche Gewissheit schließlich im mystischen Erleben des Sufismus.']},{id:'averroes',name:'Averroes (Ibn Rushd)',jahre:'1126–1198',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Islamische Philosophie','Metaphysik'],werke:['Die Inkohärenz der Inkohärenz'],kernideen:['Verteidigte Aristoteles und die Vernunft gegen al-Ghazalis Kritik.','Wird oft (vereinfachend) mit der Lehre der „doppelten Wahrheit" von Glauben und Philosophie verbunden.']},{id:'maimonides',name:'Maimonides',jahre:'1138–1204',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Islamische Philosophie','Metaphysik','Ethik'],werke:['Führer der Unschlüssigen'],kernideen:['Zentrale Figur der jüdischen Philosophie, die Aristoteles mit biblischem Denken versöhnte.','Vertrat eine rationale, oft negative (apophatische) Theologie über Gottes Eigenschaften.']},// ---- Indisch ----
{id:'buddha',name:'Siddhartha Gautama (Buddha)',jahre:'ca. 563–483 v. Chr.',epoche:'Antike',tradition:'Indisch',konzepte:['Buddhismus','Ethik'],werke:['(mündlich überliefert, u.a. im Pali-Kanon)'],kernideen:['Die Vier Edlen Wahrheiten: Leiden, seine Ursache, sein Ende und der Weg dorthin.','Anatta – das Nicht-Selbst: Es gibt kein dauerhaftes, unveränderliches Ich.','Der Achtfache Pfad als praktischer Weg zur Befreiung vom Leiden.']},{id:'nagarjuna',name:'Nagarjuna',jahre:'ca. 150–250',epoche:'Antike',tradition:'Indisch',konzepte:['Buddhismus','Metaphysik'],werke:['Mulamadhyamakakarika'],kernideen:['Begründete die Madhyamaka-Schule: Alle Dinge sind „leer" (Shunyata) von eigenständigem Wesen.','Radikalisierte die buddhistische Lehre von der wechselseitigen Bedingtheit aller Phänomene.']},{id:'patanjali',name:'Patanjali',jahre:'ca. 2. Jhd. v. Chr. – 4. Jhd. n. Chr.',epoche:'Antike',tradition:'Indisch',konzepte:['Vedanta','Ethik'],werke:['Yoga-Sutras'],kernideen:['Systematisierte Yoga als philosophischen Pfad zur Beruhigung der Geistestätigkeit.','Acht Stufen (Ashtanga) führen von ethischer Disziplin bis zur Versenkung (Samadhi).']},{id:'shankara',name:'Adi Shankara',jahre:'ca. 700–750',epoche:'Mittelalter/Scholastik',tradition:'Indisch',konzepte:['Vedanta','Metaphysik'],werke:['Kommentare zu den Upanishaden'],kernideen:['Begründete den Advaita-Vedanta: radikalen Nicht-Dualismus.','Brahman (das Absolute) und Atman (das individuelle Selbst) sind letztlich identisch.']},// ---- Ostasiatisch ----
{id:'laozi',name:'Laozi',jahre:'ca. 6. Jhd. v. Chr. (legendär)',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Daoismus','Metaphysik'],werke:['Dao De Jing'],kernideen:['Das Dao (der „Weg") ist das unbenennbare Urprinzip hinter allen Dingen.','Wu Wei – müheloses Handeln im Einklang mit dem natürlichen Lauf der Dinge, statt gegen ihn anzukämpfen.']},{id:'zhuangzi',name:'Zhuangzi',jahre:'ca. 369–286 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Daoismus','Erkenntnistheorie'],werke:['Zhuangzi'],kernideen:['Das berühmte „Schmetterlingstraum"-Gleichnis stellt die Grenze zwischen Traum und Wirklichkeit infrage.','Relativierte menschliche Urteile radikal: Perspektiven sind immer standpunktabhängig.']},{id:'konfuzius',name:'Konfuzius',jahre:'551–479 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Konfuzianismus','Ethik','Politische Philosophie'],werke:['Gespräche (Lunyu)'],kernideen:['Ren (Menschlichkeit/Güte) als zentrale Tugend gelingenden Zusammenlebens.','Li (Riten, angemessenes Verhalten) ordnet Familie und Gesellschaft in harmonische Rollenbeziehungen.','Gute Herrschaft beruht auf moralischem Vorbild, nicht auf Zwang.']},{id:'mengzi',name:'Menzius (Mengzi)',jahre:'ca. 372–289 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Konfuzianismus','Ethik'],werke:['Mengzi'],kernideen:['Vertrat, dass die menschliche Natur von Grund auf gut sei und nur kultiviert werden müsse.','Rechtfertigte unter Umständen sogar Widerstand gegen tyrannische Herrscher.']},{id:'xunzi',name:'Xunzi',jahre:'ca. 310–235 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Konfuzianismus','Ethik'],werke:['Xunzi'],kernideen:['Vertrat im Gegensatz zu Mengzi, dass die menschliche Natur von sich aus schlecht sei.','Erziehung, Riten und Gesetze seien nötig, um den Menschen zu zivilisieren.']},{id:'hanfei',name:'Han Fei',jahre:'ca. 280–233 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Politische Philosophie'],werke:['Han Feizi'],kernideen:['Begründete den Legalismus: Ordnung entsteht durch klare Gesetze und konsequente Strafen, nicht durch Tugend allein.','War tief skeptisch gegenüber dem konfuzianischen Vertrauen auf moralische Selbstkultivierung.']},{id:'dogen',name:'Dogen',jahre:'1200–1253',epoche:'Mittelalter/Scholastik',tradition:'Ostasiatisch',konzepte:['Buddhismus'],werke:['Shobogenzo'],kernideen:['Begründete die Soto-Zen-Schule in Japan.','Shikantaza („nur sitzen") – Meditation selbst ist bereits Erleuchtung, kein bloßes Mittel dazu.']},{id:'nishida',name:'Nishida Kitaro',jahre:'1870–1945',epoche:'20. Jhd.',tradition:'Ostasiatisch',konzepte:['Phänomenologie','Metaphysik'],werke:['Eine Untersuchung des Guten'],kernideen:['Begründete die Kyoto-Schule, die westliche Philosophie mit Zen-Buddhismus verband.','Entwickelte den Begriff der „reinen Erfahrung" vor jeder Trennung von Subjekt und Objekt.']},// ---- Renaissance / frühe Neuzeit ----
{id:'machiavelli',name:'Niccolò Machiavelli',jahre:'1469–1527',epoche:'Renaissance',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Der Fürst'],kernideen:['Politik als eigene Sphäre jenseits moralischer Ideale.','Machterhalt rechtfertigt pragmatisches, notfalls unmoralisches Handeln.']},{id:'bacon',name:'Francis Bacon',jahre:'1561–1626',epoche:'Renaissance',tradition:'Westlich',konzepte:['Empirismus','Erkenntnistheorie'],werke:['Novum Organum'],kernideen:['„Wissen ist Macht" – Erkenntnis dient der Naturbeherrschung.','Warnte vor „Idolen" (Denkfehlern) des Stammes, der Höhle, des Marktes und des Theaters, die klares Denken verzerren.']},{id:'descartes',name:'René Descartes',jahre:'1596–1650',epoche:'Renaissance',tradition:'Westlich',konzepte:['Rationalismus','Erkenntnistheorie'],werke:['Meditationes de Prima Philosophia','Discours de la méthode'],kernideen:['„Cogito ergo sum" – radikaler Zweifel als Methode für ein unerschütterliches Fundament des Wissens.','Begründete den neuzeitlichen Dualismus von Geist (res cogitans) und Materie (res extensa).','Nutzte das Gedankenexperiment eines allmächtigen Täuschers (böser Dämon), um zu prüfen, ob wirklich gar nichts dem Zweifel standhält.']},{id:'hobbes',name:'Thomas Hobbes',jahre:'1588–1679',epoche:'Renaissance',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Leviathan'],kernideen:['Im Naturzustand herrscht „Krieg aller gegen alle".','Nur ein starker Staat (Leviathan) sichert Frieden durch einen Gesellschaftsvertrag.']},{id:'pascal',name:'Blaise Pascal',jahre:'1623–1662',epoche:'Renaissance',tradition:'Westlich',konzepte:['Ethik','Erkenntnistheorie'],werke:['Pensées (Gedanken)'],kernideen:['„Das Herz hat seine Gründe, die die Vernunft nicht kennt" – Grenzen reiner Rationalität.','Pascals Wette: An Gott zu glauben sei rational vorteilhafter als Unglaube, selbst unter Ungewissheit.']},{id:'spinoza',name:'Baruch de Spinoza',jahre:'1632–1677',epoche:'Renaissance',tradition:'Westlich',konzepte:['Rationalismus','Metaphysik'],werke:['Ethica'],kernideen:['Pantheismus: Gott und Natur sind eins (Deus sive Natura).','Alles folgt mit geometrischer Notwendigkeit aus der einen unendlichen Substanz.','Prägte den Begriff „Conatus": das grundlegende Streben jedes Dings, im eigenen Sein zu verharren und sich selbst zu erhalten.']},{id:'leibniz',name:'Gottfried Wilhelm Leibniz',jahre:'1646–1716',epoche:'Renaissance',tradition:'Westlich',konzepte:['Rationalismus','Metaphysik'],werke:['Monadologie','Theodizee'],kernideen:['Die Welt besteht aus unteilbaren, „fensterlosen" Monaden.','Unsere Welt sei die „beste aller möglichen Welten" trotz vorhandenen Übels.']},// ---- Aufklärung ----
{id:'locke',name:'John Locke',jahre:'1632–1704',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Empirismus','Politische Philosophie'],werke:['An Essay Concerning Human Understanding','Two Treatises of Government'],kernideen:['Der Geist als „tabula rasa" – alles Wissen kommt aus Erfahrung.','Legte die Grundlage liberaler Staatstheorie und unveräußerlicher Naturrechte.']},{id:'montesquieu',name:'Montesquieu',jahre:'1689–1755',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Vom Geist der Gesetze'],kernideen:['Entwickelte das Prinzip der Gewaltenteilung (Legislative, Exekutive, Judikative).','Sah Machtmissbrauch nur durch die gegenseitige Kontrolle staatlicher Gewalten verhindert.']},{id:'rousseau',name:'Jean-Jacques Rousseau',jahre:'1712–1778',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Der Gesellschaftsvertrag','Émile'],kernideen:['Der Mensch ist von Natur aus gut, wird aber durch Gesellschaft korrumpiert.','Legitimer Staat beruht auf dem „Gemeinwillen" der Bürger.']},{id:'voltaire',name:'Voltaire',jahre:'1694–1778',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Candide','Traité sur la tolérance'],kernideen:['Scharfe Kritik an religiösem Dogmatismus und Intoleranz.','Vernunft und Toleranz als Grundpfeiler der Aufklärung.']},{id:'adamsmith',name:'Adam Smith',jahre:'1723–1790',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Der Wohlstand der Nationen','Theorie der ethischen Gefühle'],kernideen:['Die „unsichtbare Hand" des Marktes lenkt Eigeninteresse zu gesellschaftlichem Nutzen.','Sah moralisches Urteilen als Fähigkeit zur Einfühlung (Sympathie) in andere begründet.']},{id:'hume',name:'David Hume',jahre:'1711–1776',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Empirismus','Erkenntnistheorie'],werke:['A Treatise of Human Nature','An Enquiry Concerning Human Understanding'],kernideen:['Radikaler Empirismus: Kausalität ist keine logische Notwendigkeit, sondern Gewohnheit.','Stellte die rationale Begründbarkeit von Induktion selbst grundsätzlich infrage.']},{id:'kant',name:'Immanuel Kant',jahre:'1724–1804',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Erkenntnistheorie','Ethik','Metaphysik'],werke:['Kritik der reinen Vernunft','Kritik der praktischen Vernunft'],kernideen:['Kategorischer Imperativ als oberstes Moralprinzip.','Synthese aus Rationalismus und Empirismus: der Verstand strukturiert die Erfahrung aktiv mit.','Unterschied zwischen „Ding an sich" und Erscheinung.','Vollzog eine „kopernikanische Wende" in der Erkenntnistheorie: Nicht unsere Erkenntnis richtet sich nach den Gegenständen, sondern die Gegenstände erscheinen uns nach den Strukturen unseres Erkenntnisvermögens.']},// ---- Deutscher Idealismus ----
{id:'fichte',name:'Johann Gottlieb Fichte',jahre:'1762–1814',epoche:'Deutscher Idealismus',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie'],werke:['Grundlage der gesamten Wissenschaftslehre'],kernideen:['Radikalisierte Kant: Das „Ich" setzt sich selbst und erzeugt dadurch die Welt der Erfahrung.','Sah Freiheit als tätiges Selbstsetzen des Bewusstseins, nicht als bloße Gegebenheit.']},{id:'schelling',name:'Friedrich Schelling',jahre:'1775–1854',epoche:'Deutscher Idealismus',tradition:'Westlich',konzepte:['Metaphysik'],werke:['System des transzendentalen Idealismus'],kernideen:['Entwarf eine Naturphilosophie, in der Natur und Geist derselben schöpferischen Kraft entspringen.']},{id:'hegel',name:'G.W.F. Hegel',jahre:'1770–1831',epoche:'Deutscher Idealismus',tradition:'Westlich',konzepte:['Metaphysik','Politische Philosophie'],werke:['Phänomenologie des Geistes','Wissenschaft der Logik'],kernideen:['Dialektik (These–Antithese–Synthese) als Motor der Geschichte.','Der sich entfaltende „Weltgeist" verwirklicht sich fortschreitend durch Geschichte und Institutionen.','Die „Herr-Knecht-Dialektik" zeigt, wie Selbstbewusstsein erst durch den riskanten Kampf um Anerkennung zwischen zwei Bewusstseinen entsteht.']},// ---- 19. Jahrhundert ----
{id:'comte',name:'Auguste Comte',jahre:'1798–1857',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Positivismus','Erkenntnistheorie'],werke:['Cours de philosophie positive'],kernideen:['Begründete den Positivismus: Nur durch Beobachtung gesichertes Wissen zählt als Erkenntnis.','Entwarf ein „Drei-Stadien-Gesetz", nach dem Denken vom Theologischen über das Metaphysische zum Positiven fortschreitet.']},{id:'mill',name:'John Stuart Mill',jahre:'1806–1873',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Ethik','Utilitarismus','Politische Philosophie'],werke:['Utilitarianism','On Liberty'],kernideen:['Utilitarismus: Handlungen sind gut, wenn sie das größte Glück der größten Zahl fördern.','Starkes Plädoyer für individuelle Freiheit, solange niemand anderem geschadet wird.']},{id:'schopenhauer',name:'Arthur Schopenhauer',jahre:'1788–1860',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Metaphysik','Ethik'],werke:['Die Welt als Wille und Vorstellung'],kernideen:['Ein blinder, zielloser „Wille" liegt allem zugrunde und erzeugt endloses Leiden.','Erlösung nur durch ästhetische Kontemplation oder Verneinung des Willens.','Die Welt zeigt sich uns gleichzeitig als „Vorstellung" (wie sie uns erscheint) und als „Wille" (ihr blindes, strebendes inneres Wesen).']},{id:'kierkegaard',name:'Søren Kierkegaard',jahre:'1813–1855',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Ethik'],werke:['Furcht und Zittern','Entweder – Oder'],kernideen:['Vorläufer des Existentialismus: Angst als Grundstimmung der Freiheit.','Glaube als „Sprung" jenseits der Vernunft, nicht deren logische Fortsetzung.']},{id:'nietzsche',name:'Friedrich Nietzsche',jahre:'1844–1900',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Ethik','Existentialismus'],werke:['Also sprach Zarathustra','Jenseits von Gut und Böse'],kernideen:['„Gott ist tot" – Kritik an traditioneller Moral und Metaphysik.','Wille zur Macht als treibende Kraft allen Lebens.','Der Übermensch als Selbstüberwindung des bisherigen Menschen.','Unterschied zwischen „Herrenmoral" (Stolz, Stärke, Selbstbejahung) und „Sklavenmoral" (Mitleid, Demut), die aus dem Ressentiment der Schwachen gegen die Starken entstehe.']},{id:'marx',name:'Karl Marx',jahre:'1818–1883',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Metaphysik'],werke:['Das Kapital','Das Kommunistische Manifest'],kernideen:['Historischer Materialismus: Ökonomische Verhältnisse bestimmen Gesellschaft und Bewusstsein.','Klassenkampf als zentraler Motor geschichtlicher Entwicklung.']},// ---- 20. Jahrhundert ----
{id:'bergson',name:'Henri Bergson',jahre:'1859–1941',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Metaphysik'],werke:['Schöpferische Entwicklung'],kernideen:['Élan vital – eine schöpferische Lebenskraft, die Evolution über bloßen Mechanismus hinaustreibt.','Unterschied zwischen gelebter, qualitativer „Dauer" und messbarer, uniformer Uhrzeit.']},{id:'husserl',name:'Edmund Husserl',jahre:'1859–1938',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Phänomenologie','Erkenntnistheorie'],werke:['Ideen zu einer reinen Phänomenologie'],kernideen:['Begründete die Phänomenologie: „Zu den Sachen selbst" – Bewusstseinsphänomene unvoreingenommen beschreiben.','Intentionalität: Bewusstsein ist immer Bewusstsein von etwas.']},{id:'wittgenstein',name:'Ludwig Wittgenstein',jahre:'1889–1951',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Sprachphilosophie','Erkenntnistheorie'],werke:['Tractatus Logico-Philosophicus','Philosophische Untersuchungen'],kernideen:['Frühwerk: Die Grenzen unserer Sprache sind die Grenzen unserer Welt.','Spätwerk: Bedeutung entsteht durch den Gebrauch in „Sprachspielen", nicht durch feste Definitionen.']},{id:'russell',name:'Bertrand Russell',jahre:'1872–1970',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Sprachphilosophie','Erkenntnistheorie'],werke:['Principia Mathematica','Probleme der Philosophie'],kernideen:['Mitbegründer der analytischen Philosophie mit Fokus auf logische Klarheit.','Versuchte, Mathematik vollständig auf Logik zurückzuführen.']},{id:'heidegger',name:'Martin Heidegger',jahre:'1889–1976',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Phänomenologie','Metaphysik'],werke:['Sein und Zeit'],kernideen:['Untersuchung des „Daseins" und seiner Geworfenheit in die Welt.','Sein zum Tode als Grundbedingung authentischer Existenz.']},{id:'merleauponty',name:'Maurice Merleau-Ponty',jahre:'1908–1961',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Phänomenologie'],werke:['Phänomenologie der Wahrnehmung'],kernideen:['Der Leib ist nicht bloß Objekt, sondern der Ort, von dem aus wir Welt überhaupt erst wahrnehmen.']},{id:'sartre',name:'Jean-Paul Sartre',jahre:'1905–1980',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Ethik'],werke:['Das Sein und das Nichts','Der Existentialismus ist ein Humanismus'],kernideen:['„Existenz geht der Essenz voraus" – der Mensch entwirft sich selbst.','Der Mensch ist „zur Freiheit verurteilt" und trägt volle Verantwortung für sein Handeln.','Beschrieb in „Der Blick" (Le Regard), wie die bloße Anwesenheit eines anderen Menschen mich selbst zum Objekt macht und ein neues Gefühl von Scham oder Selbstbewusstsein erzeugt.']},{id:'beauvoir',name:'Simone de Beauvoir',jahre:'1908–1986',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Feminismus','Ethik'],werke:['Das andere Geschlecht'],kernideen:['„Man kommt nicht als Frau zur Welt, man wird es" – Geschlecht als gesellschaftlich geformt.','Wandte existentialistische Freiheit auf die konkrete Situation der Frau als „das Andere" an.']},{id:'camus',name:'Albert Camus',jahre:'1913–1960',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Ethik'],werke:['Der Mythos des Sisyphos','Der Mensch in der Revolte'],kernideen:['Absurdismus: Der menschliche Sinnwunsch trifft auf ein sinnfreies Universum.','Gerade darin liege die Möglichkeit trotzigen, gelebten Aufbegehrens.']},{id:'popper',name:'Karl Popper',jahre:'1902–1994',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Erkenntnistheorie','Politische Philosophie'],werke:['Logik der Forschung','Die offene Gesellschaft und ihre Feinde'],kernideen:['Falsifikationismus: Theorien lassen sich nie endgültig beweisen, nur widerlegen.','Verteidigte die „offene Gesellschaft" gegen totalitäre Geschichtsphilosophien.']},{id:'arendt',name:'Hannah Arendt',jahre:'1906–1975',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Elemente und Ursprünge totaler Herrschaft','Vita activa'],kernideen:['Analyse totalitärer Herrschaft und der „Banalität des Bösen".','Handeln als spezifisch politische, öffentliche Fähigkeit des Menschen.']},{id:'foucault',name:'Michel Foucault',jahre:'1926–1984',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Erkenntnistheorie'],werke:['Überwachen und Strafen','Die Ordnung der Dinge'],kernideen:['Macht und Wissen sind untrennbar verwoben.','Institutionen formen Subjekte über Disziplin und Diskurse, nicht nur durch offene Zwangsmittel.','Prägte den Begriff der „Biomacht": Moderne Macht reguliert nicht nur einzelne Handlungen, sondern das Leben ganzer Bevölkerungen (Geburtenraten, Gesundheit, Sexualität).']},{id:'derrida',name:'Jacques Derrida',jahre:'1930–2004',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Sprachphilosophie','Erkenntnistheorie'],werke:['Grammatologie'],kernideen:['Begründete die Dekonstruktion: Texte enthalten immer innere Widersprüche und Mehrdeutigkeiten.','Kritisierte die Vorstellung fester, stabiler Bedeutung in der westlichen Philosophietradition.']},{id:'rawls',name:'John Rawls',jahre:'1921–2002',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Eine Theorie der Gerechtigkeit'],kernideen:['Gerechte Prinzipien lassen sich hinter einem „Schleier des Nichtwissens" bestimmen.','Ungleichheiten sind nur gerechtfertigt, wenn sie den am schlechtesten Gestellten nützen.']},// ---- Gegenwart ----
{id:'butler',name:'Judith Butler',jahre:'*1956',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Feminismus','Sprachphilosophie'],werke:['Das Unbehagen der Geschlechter'],kernideen:['Gender ist performativ: Es entsteht durch wiederholte Handlungen, nicht durch eine feste innere Essenz.','Stellte die Selbstverständlichkeit binärer Geschlechterkategorien grundlegend infrage.']},{id:'singer',name:'Peter Singer',jahre:'*1946',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Ethik','Utilitarismus'],werke:['Animal Liberation','Practical Ethics'],kernideen:['Radikaler Utilitarismus: Leidensfähigkeit, nicht Spezieszugehörigkeit, begründet moralische Berücksichtigung.','Grundlage der modernen Tierethik und der Debatte um effektiven Altruismus.']},{id:'bostrom',name:'Nick Bostrom',jahre:'*1973',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Transhumanismus','Ethik'],werke:['Superintelligence','Human Enhancement'],kernideen:['Untersucht existenzielle Risiken durch fortgeschrittene KI.','Erforscht ethische Fragen der gezielten Verbesserung des Menschen durch Technologie.']},{id:'harari',name:'Yuval Noah Harari',jahre:'*1976',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Transhumanismus','Politische Philosophie'],werke:['Homo Deus','Sapiens'],kernideen:['Untersucht, wie Biotechnologie und KI die Menschheit an die Schwelle einer neuen Evolutionsstufe führen könnten.']},// ---- Weitere Vorsokratiker ----
{id:'xenophanes',name:'Xenophanes',jahre:'ca. 570–475 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie'],werke:['Fragmente'],kernideen:['Kritisierte scharf die anthropomorphen Götterbilder Homers und Hesiods: Menschen erschaffen Götter nach ihrem eigenen Bild.','Vertrat einen frühen Monotheismus-nahen Gedanken eines einzigen, unbewegten göttlichen Prinzips.']},{id:'anaxagoras',name:'Anaxagoras',jahre:'ca. 500–428 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['Fragmente'],kernideen:['Führte den „Nous" (Geist/Vernunft) als Ordnungsprinzip ein, das die ursprüngliche Mischung aller Dinge in Bewegung setzt.','Vertrat, dass „alles in allem" enthalten sei – Materie ist unendlich teilbar und durchmischt.']},{id:'empedokles',name:'Empedokles',jahre:'ca. 494–434 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Metaphysik'],werke:['Über die Natur (Fragmente)'],kernideen:['Führte die vier Elemente (Feuer, Wasser, Luft, Erde) als Grundbausteine der Wirklichkeit ein.','Zwei kosmische Kräfte, Liebe und Streit, bewirken abwechselnd Verbindung und Trennung dieser Elemente.']},{id:'cicero',name:'Marcus Tullius Cicero',jahre:'106–43 v. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Ethik','Politische Philosophie'],werke:['De Officiis','De Re Publica'],kernideen:['Übersetzte und vermittelte griechische Philosophie (Stoa, Akademie, Epikureismus) systematisch ins Lateinische.','Vertrat ein Naturrechtsdenken: Wahres Gesetz sei mit der rechten Vernunft identisch und für alle Menschen gültig.']},// ---- Mittelalterliche Mystik ----
{id:'eckhart',name:'Meister Eckhart',jahre:'ca. 1260–1328',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Scholastik'],werke:['Predigten und Traktate'],kernideen:['Christliche Mystik: Die Seele könne in völliger „Gelassenheit" (Abgeschiedenheit) unmittelbar mit dem Göttlichen eins werden.','Betonte einen inneren, oft mit der scholastischen Amtskirche in Spannung stehenden Zugang zu Gott.']},{id:'cusanus',name:'Nikolaus von Kues (Cusanus)',jahre:'1401–1464',epoche:'Mittelalter/Scholastik',tradition:'Westlich',konzepte:['Metaphysik','Erkenntnistheorie'],werke:['De Docta Ignorantia'],kernideen:['„Docta ignorantia" (gelehrtes Nichtwissen): Der menschliche Verstand kann das Unendliche (Gott) nie vollständig erfassen, sondern nur sich der eigenen Grenzen bewusst annähern.','Dachte das Universum bereits als potenziell unendlich – ein Vorläufer neuzeitlicher Kosmologie.']},{id:'bruno',name:'Giordano Bruno',jahre:'1548–1600',epoche:'Renaissance',tradition:'Westlich',konzepte:['Metaphysik'],werke:['De l\'infinito, universo e mondi'],kernideen:['Vertrat ein unendliches Universum mit unzähligen Sonnen und bewohnten Welten, lange vor moderner Astronomie.','Wurde wegen seiner Lehren 1600 von der Inquisition als Ketzer verbrannt – ein Symbol für den Konflikt zwischen freiem Denken und kirchlicher Autorität.']},// ---- Frühe Neuzeit: Feminismus & Ideologiekritik ----
{id:'wollstonecraft',name:'Mary Wollstonecraft',jahre:'1759–1797',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Feminismus','Politische Philosophie'],werke:['A Vindication of the Rights of Woman'],kernideen:['Forderte gleiche Bildung und Vernunftfähigkeit für Frauen als Grundlage für Gleichberechtigung.','Gilt als eine der ersten systematischen Vertreterinnen feministischer politischer Philosophie.']},{id:'feuerbach',name:'Ludwig Feuerbach',jahre:'1804–1872',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Metaphysik','Ethik'],werke:['Das Wesen des Christentums'],kernideen:['Religion sei eine Projektion: Der Mensch erschafft Gott nach seinem eigenen idealisierten Bild und entfremdet sich so von sich selbst.','Beeinflusste maßgeblich Marx\' Religionskritik und den Materialismus des 19. Jahrhunderts.']},// ---- Soziologie ----
{id:'weber',name:'Max Weber',jahre:'1864–1920',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Soziologie','Politische Philosophie'],werke:['Die protestantische Ethik und der Geist des Kapitalismus','Wirtschaft und Gesellschaft'],kernideen:['Untersuchte, wie protestantische Arbeitsethik zur Entstehung des modernen Kapitalismus beitrug.','Prägte den Begriff der „Entzauberung der Welt" durch fortschreitende Rationalisierung und Bürokratisierung.']},// ---- Ostasiatischer Neukonfuzianismus ----
{id:'zhuxi',name:'Zhu Xi',jahre:'1130–1200',epoche:'Mittelalter/Scholastik',tradition:'Ostasiatisch',konzepte:['Neukonfuzianismus','Metaphysik'],werke:['Kommentare zu den Vier Büchern'],kernideen:['Systematisierte den Neukonfuzianismus durch die Begriffe Li (Ordnungsprinzip) und Qi (Lebenskraft/Materie).','Seine Kommentare zu den konfuzianischen Klassikern wurden Jahrhunderte lang Grundlage der chinesischen Beamtenprüfungen.']},{id:'wangyangming',name:'Wang Yangming',jahre:'1472–1529',epoche:'Renaissance',tradition:'Ostasiatisch',konzepte:['Neukonfuzianismus','Ethik'],werke:['Anweisungen für die praktische Lebensführung'],kernideen:['Lehrte die „Einheit von Wissen und Handeln": Echtes moralisches Wissen zeigt sich erst im tatsächlichen Handeln, nicht im bloßen Verstehen.','Betonte die angeborene, intuitive moralische Erkenntnisfähigkeit („liangzhi") jedes Menschen.']},// ---- Islamische Geschichtsphilosophie & Sufismus ----
{id:'ibnkhaldun',name:'Ibn Khaldun',jahre:'1332–1406',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Politische Philosophie','Soziologie'],werke:['Muqaddima'],kernideen:['Gilt als Vorläufer der Geschichtssoziologie: Analysierte den zyklischen Aufstieg und Niedergang von Dynastien.','Prägte den Begriff „Asabiyya" (Gruppensolidarität) als treibende Kraft gesellschaftlichen Zusammenhalts und politischer Macht.']},{id:'rumi',name:'Rumi (Dschalal ad-Din)',jahre:'1207–1273',epoche:'Mittelalter/Scholastik',tradition:'Nahöstlich/Islamisch',konzepte:['Sufismus','Ethik'],werke:['Masnavi'],kernideen:['Sufistischer Mystiker und Dichter: Liebe (zu Gott und zwischen Menschen) als zentraler Weg spiritueller Erkenntnis.','Seine Poesie verbindet philosophische Tiefe mit praktischer, gefühlsbetonter Spiritualität jenseits reiner Verstandeslogik.']},// ---- Gegenwart ----
{id:'byungchulhan',name:'Byung-Chul Han',jahre:'*1959',epoche:'Gegenwart/Transhumanismus',tradition:'Ostasiatisch',konzepte:['Existentialismus','Politische Philosophie'],werke:['Müdigkeitsgesellschaft','Die Transparenzgesellschaft'],kernideen:['Diagnostiziert die heutige „Leistungsgesellschaft": Erschöpfung entsteht nicht mehr durch äußeren Zwang, sondern durch selbst auferlegten Optimierungsdruck.','Kritisiert die „Transparenzgesellschaft", in der permanente Sichtbarkeit und Selbstoffenlegung neue, subtile Formen der Kontrolle erzeugen.']},{id:'nussbaum',name:'Martha Nussbaum',jahre:'*1947',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Ethik','Politische Philosophie'],werke:['Gerechtigkeit oder Das gute Leben','Der Fähigkeitenansatz'],kernideen:['Entwickelte gemeinsam mit Amartya Sen den „Capabilities Approach": Gerechtigkeit bemisst sich daran, welche realen Fähigkeiten und Freiheiten Menschen tatsächlich zur Verfügung stehen.','Verbindet aristotelische Tugendethik mit zeitgenössischer Gerechtigkeitstheorie und Emotionsforschung.']},// ---- Afrikanische Philosophie ----
{id:'mbiti',name:'John Mbiti',jahre:'1931–2019',epoche:'20. Jhd.',tradition:'Afrikanisch',konzepte:['Afrikanische Philosophie','Metaphysik'],werke:['African Religions and Philosophy'],kernideen:['Systematisierte erstmals umfassend traditionelle afrikanische Religions- und Weltanschauungen als eigenständige Philosophie.','Beschrieb ein relationales Menschenbild, oft mit dem Satz zusammengefasst: „Ich bin, weil wir sind" (Ubuntu-Gedanke).','Betonte ein zyklisches, gemeinschaftsbezogenes Zeitverständnis im Gegensatz zu linearem westlichem Zeitdenken.']},{id:'wiredu',name:'Kwasi Wiredu',jahre:'1931–2022',epoche:'Gegenwart/Transhumanismus',tradition:'Afrikanisch',konzepte:['Afrikanische Philosophie','Politische Philosophie'],werke:['Philosophy and an African Culture'],kernideen:['Forderte eine kritische „Entkolonialisierung" des Denkens: westliche Begriffe nicht unreflektiert auf afrikanisches Denken übertragen.','Entwickelte ein Modell konsensbasierter, nicht-parteiischer Demokratie nach dem Vorbild traditioneller Ältestenräte.','Plädierte für einen interkulturellen Dialog auf Augenhöhe zwischen afrikanischer und westlicher Philosophie.']},{id:'appiah',name:'Kwame Anthony Appiah',jahre:'*1954',epoche:'Gegenwart/Transhumanismus',tradition:'Afrikanisch',konzepte:['Afrikanische Philosophie','Ethik','Politische Philosophie'],werke:['Der Kosmopolit','Identität und Gewalt'],kernideen:['Vertritt einen „verwurzelten Kosmopolitismus": Verbundenheit mit der eigenen Kultur und universelle Verantwortung schließen sich nicht aus.','Kritisiert essentialistische Vorstellungen von Rasse und kultureller Identität als zu starr und historisch konstruiert.','Plädiert für Konversation statt Konsens als Grundlage friedlichen Zusammenlebens verschiedener Kulturen.']},{id:'mbembe',name:'Achille Mbembe',jahre:'*1957',epoche:'Gegenwart/Transhumanismus',tradition:'Afrikanisch',konzepte:['Afrikanische Philosophie','Politische Philosophie'],werke:['Kritik der schwarzen Vernunft','Necropolitics'],kernideen:['Prägte den Begriff „Nekropolitik": Souveräne Macht zeigt sich nicht nur darin, wer leben darf, sondern wer sterben muss.','Analysiert postkoloniale Machtstrukturen und deren Fortwirken in globalen Wirtschafts- und Migrationsordnungen.','Untersucht, wie Rassekonzepte historisch konstruiert wurden und bis heute globale Machtverhältnisse strukturieren.']},{id:'dussel',name:'Enrique Dussel',jahre:'1934–2023',epoche:'Gegenwart/Transhumanismus',tradition:'Lateinamerikanisch',konzepte:['Befreiungsphilosophie','Ethik','Politische Philosophie'],werke:['Philosophie der Befreiung'],kernideen:['Begründete die „Philosophie der Befreiung": Denken soll explizit von der Perspektive der Unterdrückten und Ausgeschlossenen ausgehen.','Kritisierte die europäische Philosophietradition als stillschweigend eurozentrisch und blind für koloniale Gewaltgeschichte.','Entwickelte eine Ethik, die die konkrete Verletzlichkeit des „Anderen" ins Zentrum stellt.']},{id:'zea',name:'Leopoldo Zea',jahre:'1912–2004',epoche:'20. Jhd.',tradition:'Lateinamerikanisch',konzepte:['Befreiungsphilosophie','Politische Philosophie'],werke:['La Filosofía Americana como Filosofía sin más'],kernideen:['Fragte programmatisch: Kann es eine genuin „lateinamerikanische" Philosophie geben, oder ist Philosophie immer nur Kopie europäischen Denkens?','Vertrat, dass gerade die Randstellung Lateinamerikas einen eigenständigen, kritischen philosophischen Blickwinkel ermögliche.','Prägte die Geschichtsschreibung lateinamerikanischen Denkens als eigenständige philosophische Disziplin entscheidend mit.']},{id:'freire',name:'Paulo Freire',jahre:'1921–1997',epoche:'20. Jhd.',tradition:'Lateinamerikanisch',konzepte:['Kritische Pädagogik','Befreiungsphilosophie','Politische Philosophie'],werke:['Pädagogik der Unterdrückten'],kernideen:['Kritisierte die traditionelle „Bankiers-Erziehung", bei der Lehrende passiven Lernenden Wissen nur „einzahlen".','Entwickelte eine dialogische, befreiende Pädagogik: Bildung als gemeinsamer Prozess kritischen Bewusstwerdens (Konszientisierung).','Sah Alphabetisierung untrennbar mit politischer Selbstermächtigung Unterdrückter verbunden.']},// ---- Politische Philosophie: weitere Schlüsselfiguren ----
{id:'tocqueville',name:'Alexis de Tocqueville',jahre:'1805–1859',epoche:'19. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Soziologie'],werke:['Über die Demokratie in Amerika'],kernideen:['Analysierte die USA als Modellfall dafür, wie sich Demokratie in Europa entwickeln könnte – mit Chancen und Risiken zugleich.','Warnte vor der „Tyrannei der Mehrheit": Demokratien können Minderheitenmeinungen durch gesellschaftlichen Konformitätsdruck ebenso unterdrücken wie durch Gesetze.','Betonte die Rolle freiwilliger zivilgesellschaftlicher Vereinigungen als Schutz gegen übermäßige staatliche Zentralisierung und soziale Vereinzelung.']},{id:'habermas',name:'Jürgen Habermas',jahre:'*1929',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Theorie des kommunikativen Handelns','Strukturwandel der Öffentlichkeit'],kernideen:['Entwickelte die Diskursethik: Normen sind nur dann legitim, wenn sie im Prinzip die Zustimmung aller Betroffenen in einem herrschaftsfreien Diskurs finden könnten.','Prägte den Begriff der bürgerlichen „Öffentlichkeit" als Raum kritischer politischer Meinungsbildung zwischen Staat und Privatsphäre.','Vertrat eine Theorie kommunikativen Handelns, die Verständigung statt bloßer strategischer Interessendurchsetzung ins Zentrum stellt.']},{id:'berlin',name:'Isaiah Berlin',jahre:'1909–1997',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Zwei Freiheitsbegriffe'],kernideen:['Unterschied grundlegend zwischen negativer Freiheit (Freiheit von äußerem Zwang) und positiver Freiheit (Freiheit zur Selbstverwirklichung).','Warnte, dass Konzepte „positiver Freiheit" historisch leicht missbraucht wurden, um Zwang im Namen angeblich „wahrer" Selbstverwirklichung zu rechtfertigen.','Vertrat einen Werte-Pluralismus: Grundlegende Werte wie Freiheit und Gleichheit können tragisch kollidieren, ohne dass es eine einzig richtige Rangordnung gibt.']},{id:'gramsci',name:'Antonio Gramsci',jahre:'1891–1937',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Gefängnishefte'],kernideen:['Prägte den Begriff der „kulturellen Hegemonie": Herrschende sichern Macht nicht nur durch Zwang, sondern durch Verbreitung ihrer Werte als scheinbar „gesunden Menschenverstand".','Verfasste den Großteil seines Werks während faschistischer Gefängnishaft in Italien.','Betonte Kultur und Intellektuelle als eigenständiges Feld politischen Kampfes, nicht nur ökonomische Verhältnisse.']},{id:'nozick',name:'Robert Nozick',jahre:'1938–2002',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie','Libertarismus'],werke:['Anarchie, Staat, Utopia'],kernideen:['Verteidigte einen „Minimalstaat", dessen einzige legitime Aufgabe der Schutz vor Gewalt, Diebstahl und Vertragsbruch ist.','Kritisierte Rawls\' Umverteilungsgerechtigkeit scharf: Gerechte Besitzverhältnisse ergeben sich aus gerechtem Erwerb und freiwilligem Tausch, nicht aus vorgegebenen Verteilungsmustern.','Entwickelte das Gedankenexperiment der „Erlebnismaschine", um zu zeigen, dass Menschen mehr wollen als bloßes subjektives Glücksgefühl.']},{id:'paine',name:'Thomas Paine',jahre:'1737–1809',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Common Sense','Rights of Man'],kernideen:['Verfasste mit „Common Sense" eine der einflussreichsten politischen Streitschriften der Geschichte, die maßgeblich zur amerikanischen Unabhängigkeit beitrug.','Vertrat radikale Volkssouveränität: Legitime Regierung müsse direkt aus dem Willen der Bürger hervorgehen, nicht aus Erbrecht oder Monarchie.','Verteidigte in „Rights of Man" die Französische Revolution gegen Burkes Kritik und plädierte für universelle Menschenrechte.']},{id:'burke',name:'Edmund Burke',jahre:'1729–1797',epoche:'Aufklärung',tradition:'Westlich',konzepte:['Politische Philosophie','Konservatismus'],werke:['Reflections on the Revolution in France'],kernideen:['Gilt als Gründungsvater des modernen politischen Konservatismus; kritisierte die Französische Revolution scharf.','Vertrat, dass gewachsene gesellschaftliche Traditionen und Institutionen mehr praktische Weisheit enthalten als abstrakte revolutionäre Vernunftpläne.','Warnte, dass radikaler, abrupter Umsturz bestehender Ordnungen häufiger in Chaos und Tyrannei ende als in echter Freiheit.']},{id:'schmitt',name:'Carl Schmitt',jahre:'1888–1985',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Politische Philosophie'],werke:['Der Begriff des Politischen','Politische Theologie'],kernideen:['Definierte das Wesen des Politischen durch die Unterscheidung von Freund und Feind als grundlegende, nicht reduzierbare Kategorie.','Vertrat, dass der Souverän derjenige sei, „der über den Ausnahmezustand entscheidet" – also über die Aussetzung normaler Rechtsordnung in Krisenzeiten.','War NSDAP-Mitglied und rechtfertigte zeitweise das NS-Regime; seine Konzepte werden bis heute gerade wegen dieser Belastung kontrovers diskutiert.']},// ---- Weitere Antike & Ostasiatische Ergänzungen ----
{id:'hypatia',name:'Hypatia von Alexandria',jahre:'ca. 360–415 n. Chr.',epoche:'Antike',tradition:'Westlich',konzepte:['Neuplatonismus','Erkenntnistheorie'],werke:['(Kommentare zu mathematischen und astronomischen Werken, nicht erhalten)'],kernideen:['Lehrte in Alexandria Mathematik, Astronomie und neuplatonische Philosophie und galt als eine der bedeutendsten Gelehrten ihrer Zeit.','Verfasste (nicht erhaltene) Kommentare zu klassischen mathematischen und astronomischen Werken und war an der Konstruktion astronomischer Instrumente beteiligt.','Wurde 415 n. Chr. von einem aufgebrachten christlichen Mob in Alexandria ermordet – ihr Tod gilt bis heute als Symbol für den Konflikt zwischen antiker Gelehrsamkeit und religiösem Fanatismus.']},{id:'sunzi',name:'Sunzi (Sun Tzu)',jahre:'ca. 5. Jhd. v. Chr. (Lebensdaten unsicher)',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Kriegsphilosophie','Politische Philosophie'],werke:['Die Kunst des Krieges (Sunzi Bingfa)'],kernideen:['Verfasste das älteste und einflussreichste Werk der Militärstrategie, das weit über den militärischen Kontext hinaus rezipiert wird.','Vertrat, dass der größte Sieg der sei, den Feind ohne tatsächliche Schlacht zu bezwingen – durch Täuschung, Information und psychologische Überlegenheit.','Betonte gründliche Selbst- und Feindkenntnis sowie Anpassungsfähigkeit an wechselnde Umstände als Kern strategischen Denkens.']},{id:'musashi',name:'Miyamoto Musashi',jahre:'1584–1645',epoche:'Renaissance',tradition:'Ostasiatisch',konzepte:['Kriegsphilosophie','Ethik'],werke:['Gorin no Sho (Das Buch der Fünf Ringe)'],kernideen:['Berühmtester Schwertkämpfer Japans, ungeschlagen in über 60 Duellen; zog sich im Alter zur philosophischen Reflexion zurück.','Verfasste kurz vor seinem Tod „Gorin no Sho", das Schwertkampf, Strategie und Lebensführung anhand der fünf Elemente Erde, Wasser, Feuer, Wind und Leere gliedert.','Vertrat, dass wahre Meisterschaft in jedem Bereich – Kampfkunst, Handwerk, Lebensführung – denselben Prinzipien von Disziplin, Klarheit und beständiger Übung folgt.']},{id:'rikyu',name:'Sen no Rikyū',jahre:'1522–1591',epoche:'Renaissance',tradition:'Ostasiatisch',konzepte:['Ethik','Buddhismus'],werke:['Nanpō-roku (überliefert durch Schüler)'],kernideen:['Formalisierte die japanische Teezeremonie (Chanoyu) zu einer eigenständigen ästhetisch-philosophischen Praxis der Achtsamkeit.','Prägte das Ideal des Wabi-Cha: Schönheit liegt in Schlichtheit, Unvollkommenheit und Vergänglichkeit, nicht in Prunk oder Perfektion.','Wurde trotz seines enormen Einflusses am Hof des Feldherrn Toyotomi Hideyoshi später zum rituellen Selbstmord (Seppuku) gezwungen.']},{id:'shotoku',name:'Prinz Shōtoku',jahre:'574–622',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Politische Philosophie','Konfuzianismus','Buddhismus'],werke:['Siebzehn-Artikel-Verfassung (604 n. Chr.)'],kernideen:['Verfasste mit der „Siebzehn-Artikel-Verfassung" eines der ältesten politisch-ethischen Grundsatzdokumente Japans, das konfuzianische und buddhistische Ideale verband.','Stellte „Wa" (Harmonie) programmatisch an die erste Stelle: Gemeinschaftlicher Ausgleich vor individueller Rechthaberei als oberstes Staatsprinzip.','Förderte den Buddhismus als Staatsreligion und damit den kulturellen Austausch zwischen Japan, Korea und China.']},{id:'kukai',name:'Kūkai (Kōbō Daishi)',jahre:'774–835',epoche:'Mittelalter/Scholastik',tradition:'Ostasiatisch',konzepte:['Buddhismus'],werke:['Sangō Shīki','Zehn Stufen des Geistes'],kernideen:['Gründete nach einer Studienreise nach China die Shingon-Schule des esoterischen Buddhismus in Japan.','Vertrat, dass Erleuchtung „in diesem Körper" (Sokushin Jōbutsu) erreichbar sei – noch im gegenwärtigen Leben, nicht erst nach unzähligen Wiedergeburten.','Prägte japanische Kultur weit über die Religion hinaus, u.a. durch Kalligrafie und Dichtung.']},{id:'shinran',name:'Shinran',jahre:'1173–1263',epoche:'Mittelalter/Scholastik',tradition:'Ostasiatisch',konzepte:['Buddhismus'],werke:['Kyōgyōshinshō','Tannishō (überliefert durch seinen Schüler Yuien)'],kernideen:['Begründete die Jōdo-Shinshū („Wahre Schule des Reinen Landes"), eine der einflussreichsten buddhistischen Strömungen Japans bis heute.','Vertrat, dass Erlösung allein durch reines Vertrauen (Shinjin) in Amida Buddha erreichbar sei, nicht durch eigene asketische Anstrengung.','Brach radikal mit dem Mönchszölibat und heiratete selbst, um zu zeigen, dass Erleuchtung auch mitten im gewöhnlichen Leben möglich ist.']},{id:'motoori',name:'Motoori Norinaga',jahre:'1730–1801',epoche:'Aufklärung',tradition:'Ostasiatisch',konzepte:['Ethik'],werke:['Kojiki-den'],kernideen:['Zentrale Figur der Kokugaku („Nationale Gelehrsamkeit"), die japanische Klassiker gegen vorherrschenden chinesisch-konfuzianischen Einfluss neu erschloss.','Prägte den Begriff „Mono no Aware" – das wehmütige, tief empfundene Berührtsein durch die Vergänglichkeit der Dinge.','Vertrat, dass emotionale, ästhetische Empfänglichkeit näher an menschlicher Wahrheit liege als abstrakte moralische Prinzipien.']},{id:'zeami',name:'Zeami Motokiyo',jahre:'1363–1443',epoche:'Mittelalter/Scholastik',tradition:'Ostasiatisch',konzepte:['Ethik'],werke:['Fūshikaden'],kernideen:['Begründete gemeinsam mit seinem Vater die klassische Form des Noh-Theaters und verfasste die ersten systematischen Schriften zur japanischen Theaterästhetik.','Prägte den Begriff „Yūgen" – eine geheimnisvolle, tief verborgene Schönheit, die sich nur andeutet, nie vollständig zeigt.','Vertrat, dass wahre künstlerische Meisterschaft („Hana", die „Blüte") sich erst durch jahrzehntelange Übung und mit zunehmendem Alter voll entfalte.']},{id:'tsunetomo',name:'Yamamoto Tsunetomo',jahre:'1659–1719',epoche:'Renaissance',tradition:'Ostasiatisch',konzepte:['Kriegsphilosophie','Ethik'],werke:['Hagakure (aufgezeichnet durch einen Schüler)'],kernideen:['Seine Aussprüche wurden im „Hagakure" festgehalten, dem einflussreichsten Text zum Bushido-Ehrenkodex der Samurai.','Berühmt für den Grundsatz, der Weg des Samurai liege in der ständigen, bewussten Bereitschaft zum Tod.','Betonte bedingungslose Loyalität und Wachsamkeit – in bewusstem Kontrast zu Musashis eher strategisch-technischem Zugang zum Schwertweg.']},{id:'watsuji',name:'Watsuji Tetsurō',jahre:'1889–1960',epoche:'20. Jhd.',tradition:'Ostasiatisch',konzepte:['Ethik','Phänomenologie'],werke:['Fūdo (Klima und Kultur)','Rinrigaku (Ethik)'],kernideen:['Entwickelte eine Ethik der „Aidagara" (Zwischenmenschlichkeit): Der Mensch ist wesentlich durch seine Beziehungen zu anderen konstituiert, nicht als isoliertes Einzelwesen.','Untersuchte in „Fūdo", wie geografisches und klimatisches Milieu die Grundzüge einer Kultur und ihres Denkens prägen.','Verband westliche Phänomenologie (Heidegger) kritisch mit japanischem Denken und ergänzte Heideggers Zeitfokus um die Dimension des Raumes.']},{id:'nishitani',name:'Nishitani Keiji',jahre:'1900–1990',epoche:'20. Jhd.',tradition:'Ostasiatisch',konzepte:['Buddhismus','Phänomenologie'],werke:['Was ist Religion?'],kernideen:['Schüler Nishida Kitarōs und zentrale Figur der zweiten Generation der Kyoto-Schule.','Untersuchte die Konfrontation zwischen buddhistischer Leerheit (Shunyata) und dem europäischen Nihilismus Nietzsches.','Vertrat, dass echte religiöse Erfahrung erst jenseits des Nihilismus liegt – nicht als dessen bloße Verneinung, sondern als dessen radikale Durchquerung.']},// ---- Weitere Schlüsseldenker ----
{id:'montaigne',name:'Michel de Montaigne',jahre:'1533–1592',epoche:'Renaissance',tradition:'Westlich',konzepte:['Ethik','Erkenntnistheorie'],werke:['Essais'],kernideen:['Begründete mit seinen „Essais" eine neue literarische und philosophische Gattung: das offene, selbstkritische Nachdenken über das eigene Leben.','Vertrat einen milden Skeptizismus (Leitspruch „Que sais-je?" – Was weiß ich?), der vorschnelle Gewissheit grundsätzlich infrage stellte.','Plädierte für Toleranz, Selbstkenntnis und die Akzeptanz menschlicher Unvollkommenheit statt starrer moralischer Ideale.','Ließ sich in „Über die Kannibalen" von fremden Kulturen zu einem frühen kulturellen Relativismus anregen: Das eigene Gewohnte ist nicht automatisch das Vernünftigste.']},{id:'james',name:'William James',jahre:'1842–1910',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Erkenntnistheorie','Ethik'],werke:['Pragmatismus','Die Vielfalt religiöser Erfahrung'],kernideen:['Mitbegründer des Pragmatismus: Die Wahrheit einer Idee bemisst sich an ihren praktischen Konsequenzen im Leben, nicht an abstrakter Korrespondenz mit der Wirklichkeit.','Vertrat in „The Will to Believe", dass es in bestimmten existenziellen Fragen legitim sei, sich für eine Überzeugung zu entscheiden, auch ohne zwingende Beweise.','Untersuchte religiöses Erleben empirisch-psychologisch, statt es rein theologisch zu bewerten.']},{id:'jaspers',name:'Karl Jaspers',jahre:'1883–1969',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Existentialismus','Metaphysik'],werke:['Philosophie','Vom Ursprung und Ziel der Geschichte'],kernideen:['Prägte den Begriff der „Grenzsituationen" (Tod, Leiden, Schuld, Kampf) – Momente, in denen der Mensch an die Grenzen gewöhnlicher Existenz stößt und zu echter Selbsterkenntnis gezwungen wird.','Entwickelte den Begriff der „Achsenzeit" (ca. 800–200 v. Chr.), in der unabhängig voneinander in Griechenland, Indien, China und Persien die Grundlagen heutigen Denkens entstanden.','Vertrat eine Philosophie der „Kommunikation": Wahrheit erschließt sich nur im echten, offenen Austausch zwischen freien Subjekten.']},{id:'levinas',name:'Emmanuel Levinas',jahre:'1906–1995',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Ethik','Phänomenologie'],werke:['Totalität und Unendlichkeit'],kernideen:['Vertrat, dass Ethik die eigentliche „erste Philosophie" sei – noch grundlegender als Erkenntnistheorie oder Metaphysik.','Das „Antlitz des Anderen" konfrontiert uns unmittelbar mit einer ethischen Verpflichtung, die jeder rationalen Begründung vorausgeht.','Kritisierte die abendländische Philosophietradition, das Andere zu oft dem eigenen Denken einzuverleiben, statt seine radikale Fremdheit anzuerkennen.']},{id:'weil',name:'Simone Weil',jahre:'1909–1943',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Ethik','Metaphysik'],werke:['Schwerkraft und Gnade'],kernideen:['Vertrat, dass echte Aufmerksamkeit (Attention) die höchste und seltenste Form des Gebets und der Nächstenliebe sei.','Arbeitete zeitweise bewusst in Fabriken und auf Feldern, um die Lebensrealität der Arbeiterklasse aus eigener Erfahrung zu verstehen.','Verband christliche Mystik mit scharfer Sozialkritik und tiefem Misstrauen gegenüber institutioneller Macht, auch kirchlicher.']},{id:'hooks',name:'bell hooks',jahre:'1952–2021',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Feminismus','Ethik'],werke:['All About Love'],kernideen:['Verband in ihrem Werk konsequent Feminismus, Rassismuskritik und Klassenanalyse als untrennbar miteinander verwoben.','Vertrat in „All About Love", dass Liebe eine bewusste, aktive Praxis und Entscheidung sei, kein bloßes passives Gefühl.','Kritisierte patriarchale Männlichkeitsbilder als schädlich auch für Männer selbst, nicht nur für Frauen.']},{id:'watts',name:'Alan Watts',jahre:'1915–1973',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Buddhismus','Daoismus'],werke:['Der Lauf des Wassers','Die Weisheit des Ungewissen'],kernideen:['Trug maßgeblich dazu bei, Zen-Buddhismus und daoistisches Denken einem breiten westlichen Publikum verständlich zu machen.','Vertrat, dass das Ich als fest abgegrenzte, isolierte Einheit eine Illusion sei – wir seien untrennbar mit dem gesamten Universum verwoben.','Betonte, dass wahres Leben nur im gegenwärtigen Moment stattfindet, nicht in ständiger Sorge um Vergangenheit oder Zukunft.']},// ---- Philosophie des Geistes ----
{id:'nagel',name:'Thomas Nagel',jahre:'*1937',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Philosophie des Geistes','Erkenntnistheorie'],werke:['Wie ist es, eine Fledermaus zu sein?'],kernideen:['Argumentierte, dass subjektives Erleben (Qualia) sich grundsätzlich nicht vollständig in objektive, dritte-Person-Begriffe übersetzen lässt.','Vertrat, dass zwischen physikalischer Beschreibung und subjektivem Erleben ein unüberbrückbarer Erklärungsgraben klafft.','Kritisierte reduktionistischen Physikalismus als unfähig, das eigentliche Wesen von Bewusstsein zu erfassen.']},{id:'chalmers',name:'David Chalmers',jahre:'*1966',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Philosophie des Geistes'],werke:['Das bewusste Erleben'],kernideen:['Unterschied zwischen dem „leichten" Problem des Bewusstseins (neuronale Mechanismen erklären) und dem „harten Problem": warum physikalische Prozesse überhaupt von subjektivem Erleben begleitet werden.','Entwickelte das Gedankenexperiment der „philosophischen Zombies" – Wesen, die sich physisch identisch verhalten wie wir, aber kein inneres Erleben hätten.','Vertrat einen naturalistischen Dualismus: Bewusstsein sei eine fundamentale Eigenschaft der Wirklichkeit, nicht auf Physisches reduzierbar.']},{id:'dennett',name:'Daniel Dennett',jahre:'1942–2024',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Philosophie des Geistes'],werke:['Consciousness Explained'],kernideen:['Vertrat einen konsequenten Funktionalismus: Bewusstsein sei letztlich durch neuronale und kognitive Prozesse vollständig erklärbar, ohne mysteriösen Rest.','Kritisierte die Vorstellung eines „Cartesianischen Theaters" – einer zentralen Bühne im Gehirn, auf der Bewusstsein „geschieht".','Bezeichnete Chalmers\' „hartes Problem" des Bewusstseins als letztlich ein Scheinproblem, das aus irreführenden Intuitionen entsteht.']},{id:'searle',name:'John Searle',jahre:'*1932',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Philosophie des Geistes','Sprachphilosophie'],werke:['Minds, Brains, and Programs'],kernideen:['Entwickelte das Gedankenexperiment des „Chinesischen Zimmers": Reine Regelbefolgung bei der Symbolmanipulation erzeugt kein echtes Verstehen.','Vertrat, dass Syntax (Symbolverarbeitung) allein niemals Semantik (Bedeutung, echtes Verstehen) erzeugen kann.','Unterschied zwischen „starker KI" (Computer könnten wirklich denken) und „schwacher KI" (Computer simulieren nur Denken).']},{id:'jackson',name:'Frank Jackson',jahre:'*1943',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Philosophie des Geistes'],werke:['Epiphenomenal Qualia'],kernideen:['Entwickelte das Gedankenexperiment „Marys Zimmer": Eine Farbforscherin, die alle physikalischen Fakten über Farbe kennt, aber ihr Leben lang nur schwarz-weiß sah, lernt beim ersten echten Sehen von Rot dennoch etwas Neues.','Nutzte dieses „Wissensargument", um zu zeigen, dass es neben physikalischem Wissen noch etwas Weiteres gibt: das subjektive Erleben selbst (Qualia).','Vertrat ursprünglich einen Eigenschaftsdualismus, revidierte seine Position in späteren Jahren teilweise zugunsten des Physikalismus.']},// ---- Mohismus ----
{id:'mozi',name:'Mozi',jahre:'ca. 470–391 v. Chr.',epoche:'Antike',tradition:'Ostasiatisch',konzepte:['Mohismus','Ethik','Kriegsphilosophie'],werke:['Mozi (Textsammlung der Schule)'],kernideen:['Begründete den Mohismus als scharfen Gegenentwurf zum Konfuzianismus seiner Zeit.','Vertrat „Jian Ai" (universelle, ungeteilte Nächstenliebe): Man solle alle Menschen gleichermaßen lieben, nicht abgestuft nach Familie und sozialem Rang.','Vertrat radikalen Pazifismus („Fei Gong" – gegen Angriffskriege) und entwickelte praktische Verteidigungstechniken gegen Belagerungen.','Argumentierte konsequentialistisch: Handlungen und Institutionen sollten am gesellschaftlichen Gesamtnutzen gemessen werden – eine frühe Vorform utilitaristischen Denkens.']},// ---- Angewandte Ethik / Trolley-Problem ----
{id:'foot',name:'Philippa Foot',jahre:'1920–2010',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Ethik'],werke:['Das Problem der Abtreibung und die Doktrin der Doppelwirkung'],kernideen:['Führte 1967 das „Trolley-Problem" in die philosophische Debatte ein, um den moralischen Unterschied zwischen aktivem Handeln und bloßem Unterlassen zu untersuchen.','Kritisierte reinen Konsequentialismus und knüpfte an aristotelische Tugendethik an, um sie für die Gegenwart neu zu beleben.','Prägte die Doktrin der Doppelwirkung neu: Ein Schaden als vorhergesehene Nebenfolge einer guten Handlung ist moralisch anders zu bewerten als derselbe Schaden als direktes Mittel.']},{id:'thomson',name:'Judith Jarvis Thomson',jahre:'1929–2020',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Ethik'],werke:['The Trolley Problem','A Defense of Abortion'],kernideen:['Erweiterte das Trolley-Problem um die „Fat Man"-Variante: Ist es erlaubt, eine Person aktiv zu opfern, um fünf zu retten, obwohl beide Varianten dieselbe Opferzahl haben?','Entwickelte in „A Defense of Abortion" das einflussreiche Gedankenexperiment des unfreiwillig angeschlossenen Geigers, um Fragen der Abtreibung neu zu durchdenken.','Untersuchte systematisch, warum moralische Intuitionen bei strukturell ähnlichen Fällen (Umlenken vs. Stoßen) oft widersprüchlich ausfallen.']},// ---- Kommunitarismus & Wissenschaftstheorie ----
{id:'sandel',name:'Michael Sandel',jahre:'*1953',epoche:'Gegenwart/Transhumanismus',tradition:'Westlich',konzepte:['Politische Philosophie','Ethik'],werke:['Gerechtigkeit: Wie wir das Richtige tun','Was man für Geld nicht kaufen sollte'],kernideen:['Vertritt einen Kommunitarismus, der Rawls\' liberalen Universalismus kritisiert: Der Mensch ist immer schon in Gemeinschaften, Traditionen und Rollen eingebettet, nicht ein „unbelastetes" abstraktes Individuum.','Argumentiert, dass Gerechtigkeit nicht neutral gegenüber Vorstellungen des guten Lebens sein kann – Politik muss substanzielle moralische Fragen offen diskutieren, statt sie ins Private zu verschieben.','Kritisiert in „Was man für Geld nicht kaufen sollte" die zunehmende Ausweitung von Marktlogik auf Bereiche wie Bildung und Bürgerschaft, die eigentlich nicht-marktförmige Werte verkörpern.']},{id:'kuhn',name:'Thomas Kuhn',jahre:'1922–1996',epoche:'20. Jhd.',tradition:'Westlich',konzepte:['Erkenntnistheorie'],werke:['Die Struktur wissenschaftlicher Revolutionen'],kernideen:['Prägte den Begriff des „Paradigmas": ein von einer wissenschaftlichen Gemeinschaft geteiltes Set an Grundannahmen, Methoden und Beispielen.','Vertrat, dass Wissenschaft nicht linear-kumulativ fortschreitet, sondern in Phasen „normaler Wissenschaft" verläuft, die periodisch durch „wissenschaftliche Revolutionen" (Paradigmenwechsel) unterbrochen werden.','Argumentierte, dass konkurrierende Paradigmen oft „inkommensurabel" seien – Wissenschaftler in unterschiedlichen Paradigmen sähen buchstäblich verschiedene Welten.']},
{"id":"mahavira","name":"Mahavira","jahre":"ca. 599–527 v. Chr. (traditionelle Datierung; Forschung setzt ihn eher rund ein Jahrhundert später, etwa zeitgleich mit Buddha)","epoche":"Antike","tradition":"Indisch","konzepte":["Jainismus","Ethik","Metaphysik"],"werke":["Lehren überliefert in den Agamas"],"kernideen":["Letzter der 24 Tirthankaras und Reformator der jainistischen Ordensgemeinschaft; systematisierte die Lehre seines Vorgängers Parshvanatha.","Ahimsa – Gewaltlosigkeit gegenüber allem Lebendigen – als ausnahmslose Pflicht, verbunden mit den fünf großen Gelübden der Entsagung.","Anekantavada, die Vielseitigkeit der Wirklichkeit: Jede Aussage erfasst nur eine Perspektive, erst mehrere Blickwinkel nähern sich der Sache an."]},
{"id":"vasubandhu","name":"Vasubandhu","jahre":"ca. 4./5. Jhd.","epoche":"Antike","tradition":"Indisch","konzepte":["Buddhismus","Philosophie des Geistes","Erkenntnistheorie"],"werke":["Abhidharmakosha","Vimshatika (Zwanzig Verse)"],"kernideen":["Begründete zusammen mit seinem Bruder Asanga die Yogachara-Schule: Was wie eine äußere Welt erscheint, sind Vorstellungen des Bewusstseins.","Verfasste vor seiner Hinwendung zum Mahayana den Abhidharmakosha, die maßgebliche Systematisierung der Sarvastivada-Lehre.","Verfeinerte die indische Schlusslehre, indem er das förmliche Argument im Streitgespräch (fünf Schritte) vom Denken für sich selbst (drei Schritte) trennte."]},
{"id":"dignaga","name":"Dignaga","jahre":"ca. 480–540","epoche":"Mittelalter/Scholastik","tradition":"Indisch","konzepte":["Buddhismus","Erkenntnistheorie"],"werke":["Pramanasamuccaya"],"kernideen":["Legte mit dem Pramanasamuccaya das Fundament der buddhistischen Logik und Erkenntnistheorie.","Definierte Wahrnehmung neu als Erkennen, das frei von jeder begrifflichen Konstruktion ist – Namen und Gattungen kommen erst danach hinzu.","Die Apoha-Lehre: Ein Begriff bezeichnet nichts Positives, sondern grenzt aus – „Kuh\" heißt zunächst „nicht Nicht-Kuh\"."]},
{"id":"dharmakirti","name":"Dharmakirti","jahre":"frühes 7. Jhd.","epoche":"Mittelalter/Scholastik","tradition":"Indisch","konzepte":["Buddhismus","Erkenntnistheorie"],"werke":["Pramanavarttika"],"kernideen":["Führte Dignagas Ansatz zur wirkmächtigsten erkenntnistheoretischen Schule des indischen Buddhismus aus.","Nur zwei Erkenntnisquellen gelten: Wahrnehmung und Schlussfolgerung – alles andere führt in Streit ohne Grundlage.","Prüfstein gültiger Erkenntnis ist ihre Verlässlichkeit im Handeln, nicht die Übereinstimmung mit einer Autorität."]},
{"id":"ramanuja","name":"Ramanuja","jahre":"1017–1137 (traditionelle Angabe, ergäbe 120 Lebensjahre; neuere Forschung nennt 1077–1157)","epoche":"Mittelalter/Scholastik","tradition":"Indisch","konzepte":["Vedanta","Metaphysik"],"werke":["Shribhashya","Vedarthasamgraha"],"kernideen":["Hauptvertreter des Vishishtadvaita, des „qualifizierten Nicht-Dualismus\": Die Seele ist nicht identisch mit Brahman, aber auch nicht von ihm getrennt – sie ist ein Aspekt davon.","Wandte sich gegen Shankaras strengen Monismus: Vielheit, Personen und Eigenschaften sind wirklich, nicht bloßer Schein.","Räumte der liebenden Hingabe an einen persönlichen Gott (Bhakti) den Rang eines Erkenntnisweges ein."]},
{"id":"aurobindo","name":"Sri Aurobindo","jahre":"1872–1950","epoche":"20. Jhd.","tradition":"Indisch","konzepte":["Vedanta","Metaphysik"],"werke":["The Life Divine (1939)","The Synthesis of Yoga (1948)","Savitri (1950)"],"kernideen":["Entwarf den Integralen Yoga, der Körper, Geist und göttliche Ebene verbinden statt eine gegen die andere ausspielen soll.","Verwarf die Befreiung aus dem Kreislauf der Wiedergeburt als höchstes Ziel: Ziel sei ein verwandeltes Leben auf der Erde, nicht die Flucht daraus.","Deutete Evolution spirituell – der Mensch ist ein Übergangswesen, nicht der Endpunkt."]},
{"id":"ambedkar","name":"B. R. Ambedkar","jahre":"1891–1956","epoche":"20. Jhd.","tradition":"Indisch","konzepte":["Politische Philosophie","Ethik","Buddhismus"],"werke":["Annihilation of Caste (1936)","The Buddha and His Dhamma (1957, posthum)"],"kernideen":["Griff das Kastenwesen an der Wurzel an: Es sei keine Arbeitsteilung, sondern eine Teilung der Arbeitenden, und lasse sich nicht reformieren, sondern nur abschaffen.","Hauptarchitekt der indischen Verfassung; verband die Frage sozialer Gleichheit mit der Frage politischer Rechte.","Trat 1956 mit rund 200.000 Dalits in Nagpur zum Buddhismus über und legte mit „The Buddha and His Dhamma\" eine eigene, sozial gewendete Deutung vor."]},
{"id":"zerayacob","name":"Zera Yacob","jahre":"17. Jhd. (Hatata auf 1667 datiert)","epoche":"Aufklärung","tradition":"Afrikanisch","konzepte":["Rationalismus","Erkenntnistheorie","Afrikanische Philosophie"],"werke":["Hatata (Untersuchung)"],"kernideen":["Prüft im Hatata die überlieferten Religionen an der Vernunft: Keine kann ihre Sonderstellung begründen, weil jede sich auf ihre eigene Schrift beruft.","Setzt die von Gott gegebene Vernunft als Maßstab – auch gegen kirchliche Autorität, Fastengebote und die Geringschätzung der Frau.","Zuschreibung ist umstritten: Carlo Conti Rossini hielt den Text 1920 für eine Fälschung des Missionars Giusto d'Urbino; Claude Sumner und Getatchew Haile widersprachen, Anaïs Wion stützt die Fälschungsthese. Eine 2023 erschienene Edition geht von zwei äthiopischen Verfassern aus. Die Frage ist offen."]},
{"id":"amo","name":"Anton Wilhelm Amo","jahre":"ca. 1703 – nach 1753","epoche":"Aufklärung","tradition":"Afrikanisch","konzepte":["Philosophie des Geistes","Rationalismus","Afrikanische Philosophie"],"werke":["De humanae mentis apatheia (1734)","Tractatus de arte sobrie et accurate philosophandi (1738)"],"kernideen":["Als Kind aus Axim an der heutigen ghanaischen Küste nach Europa verschleppt; erster Afrikaner mit einer europäischen Promotion, später Dozent in Halle und Jena.","Widersprach Descartes an einem präzisen Punkt: Wenn der Geist reine Tätigkeit ist, kann er nicht passiv Sinneseindrücke empfangen – Empfinden gehört dem lebendigen Körper, nicht dem Geist.","Kehrte um 1747 nach Axim zurück, nach dem Tod seines Förderers und unter wachsendem Rassismus."]},
{"id":"hountondji","name":"Paulin Hountondji","jahre":"1942–2024","epoche":"20. Jhd.","tradition":"Afrikanisch","konzepte":["Afrikanische Philosophie","Erkenntnistheorie"],"werke":["Sur la « philosophie africaine » (1976)"],"kernideen":["Prägte den Kampfbegriff „Ethnophilosophie\" für den Versuch, afrikanisches Denken als anonyme Kollektivweisheit darzustellen – ohne benennbare Denker, die für ihre Thesen einstehen.","Kritisierte in dieser Linie Placide Tempels' „Bantu-Philosophie\" und deren Nachfolger, darunter John Mbiti.","Forderte eine afrikanische Philosophie, die sich an allgemeinen Maßstäben der Vernunft und wissenschaftlicher Methode messen lässt."]},
{"id":"oderaoruka","name":"Henry Odera Oruka","jahre":"1944–1995","epoche":"20. Jhd.","tradition":"Afrikanisch","konzepte":["Afrikanische Philosophie","Erkenntnistheorie"],"werke":["Sage Philosophy (1990)"],"kernideen":["Begründete Mitte der 1970er an der Universität Nairobi das Sage-Philosophy-Projekt: Er befragte Weise in kenianischen Gemeinschaften systematisch und schrieb ihre Argumente unter ihren Namen auf.","Wollte damit belegen, dass kritisches Nachdenken über Person, Freiheit, Tod und höchstes Wesen in afrikanischen Gesellschaften immer die Sache einzelner Köpfe war – nicht eines Kollektivs.","Unterschied zwischen bloßer Volksweisheit und der Sagacity jener Einzelnen, die überlieferte Ansichten selbst prüfen und auch verwerfen."]},
{"id":"sorjuana","name":"Sor Juana Inés de la Cruz","jahre":"1648 oder 1651–1695 (Geburtsjahr ohne Forschungskonsens)","epoche":"Aufklärung","tradition":"Lateinamerikanisch","konzepte":["Feminismus","Erkenntnistheorie"],"werke":["Respuesta a sor Filotea de la Cruz (1691)","Primero sueño (1692)"],"kernideen":["Verteidigte in der „Respuesta\" das Recht der Frauen auf Bildung – mit einer langen Reihe gelehrter Frauen aus Bibel, Antike und Gegenwart als Beleg.","Ging ins Kloster, weil das Ordensleben ihr mehr Zeit zum Studieren ließ als jede andere Lebensform, die einer Frau ihrer Zeit offenstand.","„Primero sueño\" schildert den nächtlichen Aufstieg der Seele zur Erkenntnis – und ihr Scheitern: Der Verstand erfasst das Ganze nicht auf einmal."]},
{"id":"mariategui","name":"José Carlos Mariátegui","jahre":"1894–1930","epoche":"20. Jhd.","tradition":"Lateinamerikanisch","konzepte":["Politische Philosophie","Befreiungsphilosophie"],"werke":["Siete ensayos de interpretación de la realidad peruana (1928)"],"kernideen":["Erster peruanischer Intellektueller, der den historischen Materialismus auf die Verhältnisse seines Landes anwandte – ohne ihn schematisch zu übernehmen.","Führte die Ausbeutung der indigenen Bevölkerung auf die Enteignung ihres Gemeinschaftslandes zurück und band die Zukunft Perus an deren Befreiung.","Hielt gegen den orthodoxen Marxismus an der Kraft von Mythos, Religion und Kunst fest: Ohne sie bewege sich niemand."]},
{"id":"gutierrez","name":"Gustavo Gutiérrez","jahre":"1928–2024","epoche":"20. Jhd.","tradition":"Lateinamerikanisch","konzepte":["Befreiungsphilosophie","Ethik"],"werke":["Teología de la liberación (1971)"],"kernideen":["Begründete die Befreiungstheologie: Armut ist kein Schicksal, sondern Ergebnis von Strukturen, die sich ändern lassen.","Prägte die „vorrangige Option für die Armen\" – der Blick von unten als Ausgangspunkt, nicht als Nachgedanke.","Setzte Orthopraxie vor Orthodoxie: Woran jemand glaubt, zeigt sich am Handeln, nicht am Bekenntnis."]},
{"id":"quijano","name":"Aníbal Quijano","jahre":"1928–2018","epoche":"20. Jhd.","tradition":"Lateinamerikanisch","konzepte":["Befreiungsphilosophie","Politische Philosophie"],"werke":["Colonialidad del poder, eurocentrismo y América Latina (2000)"],"kernideen":["Prägte den Begriff „Kolonialität der Macht\": Die Kolonialherrschaft endete, ihr Ordnungsmuster nicht – es sortiert die Weltbevölkerung weiterhin nach der Idee „Rasse\".","Diese Kolonialität wirke in vier Bereichen fort: Autorität, Arbeit und Ökonomie, Geschlecht und Sexualität sowie Wissen und Subjektivität.","Stellte damit die Selbstverständlichkeit infrage, dass europäische Begriffe der neutrale Maßstab für Erkenntnis seien."]},
{"id":"alkindi","name":"Al-Kindi","jahre":"ca. 800 – ca. 870","epoche":"Mittelalter/Scholastik","tradition":"Nahöstlich/Islamisch","konzepte":["Islamische Philosophie","Metaphysik"],"werke":["Über die erste Philosophie"],"kernideen":["Gilt als „Philosoph der Araber\": der erste, der griechische Philosophie in arabischer Sprache eigenständig weiterdachte.","Leitete einen der beiden großen Übersetzerkreise des 9. Jahrhunderts, der philosophische und wissenschaftliche Werke aus dem Griechischen ins Arabische brachte.","Hielt Wahrheit für herkunftsunabhängig: Man solle sie annehmen, woher sie auch komme – auch von fremden Völkern."]},
{"id":"ibnarabi","name":"Ibn Arabi","jahre":"1165–1240","epoche":"Mittelalter/Scholastik","tradition":"Nahöstlich/Islamisch","konzepte":["Islamische Philosophie","Sufismus","Metaphysik"],"werke":["Al-Futuhat al-Makkiyya","Fusus al-hikam (1229)"],"kernideen":["Gab der mystischen Seite islamischen Denkens ihre erste ausgearbeitete philosophische Gestalt.","Ihm wird die Lehre von der „Einheit des Seins\" (wahdat al-wujud) zugeschrieben – der Ausdruck selbst stammt allerdings nicht von ihm, sondern von späteren Auslegern.","Nur Gott ist im eigentlichen Sinn wirklich; alles andere ist für sich genommen ohne Bestand."]},
{"id":"ibntufayl","name":"Ibn Tufayl","jahre":"ca. 1110–1185","epoche":"Mittelalter/Scholastik","tradition":"Nahöstlich/Islamisch","konzepte":["Islamische Philosophie","Erkenntnistheorie"],"werke":["Hayy ibn Yaqzan (ca. 1175)"],"kernideen":["Schrieb mit „Hayy ibn Yaqzan\" den vielleicht ersten philosophischen Roman: Ein Mensch wächst allein auf einer Insel auf und entwickelt aus reiner Beobachtung ein vollständiges Weltbild.","Das Gedankenexperiment behauptet, Vernunft allein könne zur selben Einsicht führen wie die Offenbarung – ohne Lehrer, Buch oder Gemeinschaft.","Das Buch wurde im 17. und 18. Jahrhundert in Europa zum Bestseller und wirkte auf die Debatte über angeborenes und erworbenes Wissen."]},
{"id":"mullasadra","name":"Mulla Sadra","jahre":"ca. 1571–1640","epoche":"Renaissance","tradition":"Nahöstlich/Islamisch","konzepte":["Islamische Philosophie","Metaphysik"],"werke":["Al-Asfar al-arbaa (Die vier Reisen, 1606–1628)"],"kernideen":["Bedeutendster islamischer Philosoph nach Avicenna; verband schulmäßige Beweisführung mit mystischer Schau.","Lehre von der substantiellen Bewegung: Nicht nur Eigenschaften wandeln sich, sondern die Substanz der Dinge selbst ist im Fluss.","Setzte das Sein vor das Wesen – wirklich ist zunächst, dass etwas ist, nicht was es ist."]},
{"id":"wonhyo","name":"Wonhyo","jahre":"617–686","epoche":"Mittelalter/Scholastik","tradition":"Ostasiatisch","konzepte":["Buddhismus","Metaphysik"],"werke":["Kommentare zum Erwachen des Glaubens"],"kernideen":["Bedeutendster Denker des koreanischen Buddhismus; brachte die zerstrittenen Lehrrichtungen in eine Ordnung, die Gelehrten wie Laien einleuchtete.","Hwajaeng, das Versöhnen des Streits: Jede Schule sieht einen Ausschnitt des Ganzen; die Streitigkeiten entstehen aus der Sprache, nicht aus der Sache.","Sein Erwachen erlebte er der Überlieferung nach in einer Höhle, wo er nachts Wasser aus einem Schädel trank – bekömmlich, bis er am Morgen sah, woraus er getrunken hatte."]},
{"id":"yihwang","name":"Yi Hwang (T'oegye)","jahre":"1501–1570","epoche":"Renaissance","tradition":"Ostasiatisch","konzepte":["Neukonfuzianismus","Ethik"],"werke":["Beiträge zum Vier-Sieben-Streit (ab 1559)"],"kernideen":["Löste 1559 den Vier-Sieben-Streit aus, das wichtigste intellektuelle Ereignis der koreanischen konfuzianischen Geistesgeschichte.","Unterschied die vier moralischen Regungen, die aus reinem Prinzip hervorgehen und nur gut sein können, von den sieben Gefühlen, in die Lebenskraft eingeht und die gut oder schlecht ausfallen.","Damit stand die Frage im Raum, ob das moralisch Gute eine eigene Quelle hat oder nur eine gelungene Form gewöhnlicher Regungen ist."]}];
